const raw = $input.first().json;
const lead = raw.body || raw;

// Normalize field names (accepts both camelCase and snake_case)
const email = lead.lead_email || lead.email || lead.emailBestGuess || '';
const firstName = lead.first_name || lead.firstName || '';
const company = lead.company || '';

if (!email) throw new Error('Missing required field: lead_email');
if (!firstName) throw new Error('Missing required field: first_name');
if (!company) throw new Error('Missing required field: company');

// Basic email validation
if (!/^[^@]+@[^@]+\.[^@]+$/.test(email)) throw new Error('Invalid email: ' + email);

const now = new Date().toISOString();

return [{
  json: {
    lead_email: email,
    first_name: firstName,
    last_name: lead.last_name || lead.lastName || '',
    company: company,
    job_title: lead.job_title || lead.jobTitle || lead.headline || '',
    industry: lead.industry || '',
    additional_info: (lead.additional_info || lead.additionalInfo || '').substring(0, 500),
    linkedin_url: lead.linkedin_url || lead.linkedinProfileUrl || '',
    score: lead.score || lead.icpScore || '',
    touch_sent: 0,
    status_after: 'active',
    sent_at: '',
    next_send_at: now,
    enqueued_at: now
  }
}];
